input.command:
if [ -z "$GITLAB_TOKEN" ]; then
  echo "GITLAB_TOKEN not set"
  exit 1
fi

curl -s --header "PRIVATE-TOKEN: $GITLAB_TOKEN" \
  "https://mygitlab-dev.ioh.co.id/api/v4/projects/cco%2Fcmo%2Fgroup-digital-coe%2Fdiv-smb-digital-product%2Fide-phoenix/merge_requests/251" | \
  python3 -c "import sys, json; mr = json.load(sys.stdin); print(f'''Title: {mr['title']}
Description: {mr['description'][:500] if mr['description'] else 'N/A'}
Source Branch: {mr['source_branch']}
Target Branch: {mr['target_branch']}
Author: {mr['author']['name']}
Status: {mr['state']}
Web URL: {mr['web_url']}
Diff Refs:
  base_sha: {mr['diff_refs']['base_sha']}
  start_sha: {mr['diff_refs']['start_sha']}
  head_sha: {mr['diff_refs']['head_sha']}''')"
